<?php require __DIR__.'/app/bootstrap.php';$products=query('SELECT p.id,p.name,p.slug,p.price,p.image,p.back_image,p.source_images,p.category,p.sku,EXISTS(SELECT 1 FROM variants v WHERE v.product_id=p.id AND (v.stock IS NULL OR v.stock>0)) AS available FROM products p WHERE active=1 ORDER BY available DESC,created_at DESC,id DESC')->fetchAll();$categories=['T-shirts','Hoodies','Lowers'];$counts=[];
foreach($products as &$product){$category=trim($product['category']??'');if(strcasecmp($category,'Cargo Pants')===0)$category='Lowers';if(strcasecmp($category,'T-Shirts')===0)$category='T-shirts';$product['category']=$category;if($category!==''){if(!in_array($category,$categories,true))$categories[]=$category;$counts[$category]=($counts[$category]??0)+1;}}unset($product);
$selected=is_string($_GET['category']??null)?$_GET['category']:'';
if(!in_array($selected,$categories,true))$selected='';
$total=count($products);if($selected!=='')$products=array_values(array_filter($products,fn($p)=>$p['category']===$selected));
$search=substr(trim((string)($_GET['q']??'')),0,100);$size=(string)($_GET['size']??'');if(!in_array($size,sizes(),true))$size='';$stock=(string)($_GET['stock']??'');$sort=(string)($_GET['sort']??'');
$sizeIds=$size!==''?array_column(query('SELECT product_id FROM variants WHERE size=? AND (stock IS NULL OR stock>0)',[$size])->fetchAll(),'product_id'):[];
$products=array_values(array_filter($products,fn($p)=>($search===''||stripos($p['name'].' '.($p['sku']??''),$search)!==false)&&($size===''||in_array($p['id'],$sizeIds))&&($stock!=='available'||$p['available'])));
if($sort==='price-low')usort($products,fn($a,$b)=>(int)$a['price']<=>(int)$b['price']);
if($sort==='price-high')usort($products,fn($a,$b)=>(int)$b['price']<=>(int)$a['price']);
$GLOBALS['storefront_theme']=true;render_header('Street culture. Your way.'); ?>
